from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Literal

from core.artifact_registry import (
    Artifact,
    ArtifactRegistry,
    is_link_or_reparse_point,
    same_path,
)


ArtifactOrigin = Literal[
    "Generated by Qronos",
    "Downloaded by Qronos",
    "Captured by Qronos",
    "Exported by Qronos",
    "Collected by Qronos",
]

_ALLOWED_ORIGINS: set[str] = {
    "Generated by Qronos",
    "Downloaded by Qronos",
    "Captured by Qronos",
    "Exported by Qronos",
    "Collected by Qronos",
}


@dataclass(frozen=True)
class ArtifactProvenance:
    conversation_id: str = ""
    message_id: str = ""
    request_id: str = ""


class ArtifactProducerRegistry:
    """
    Single producer-facing registration boundary for Qronos artifacts.

    Producers should use this service instead of writing directly to the
    Library SQLite database. Registration never accepts an arbitrary
    "user file" classification: the caller must explicitly declare how
    Qronos produced or collected the artifact.
    """

    def __init__(self, registry: ArtifactRegistry | None = None) -> None:
        self.registry = registry or ArtifactRegistry()

    def register_file(
        self,
        path: str | Path,
        *,
        origin: ArtifactOrigin,
        provenance: ArtifactProvenance = ArtifactProvenance(),
        unread: bool = True,
    ) -> Artifact:
        if origin not in _ALLOWED_ORIGINS:
            raise ValueError(f"Unsupported Qronos artifact origin: {origin}")
        # Registration is what later lets the Library move or recycle a file,
        # so it is limited to files inside the Qronos artifact root. Without
        # this, any caller could adopt an arbitrary user file into the Library.
        candidate = Path(path).expanduser()
        if is_link_or_reparse_point(candidate):
            raise PermissionError("Links and reparse points cannot be registered as artifacts.")
        resolved = candidate.resolve(strict=True)
        root = Path(self.registry.artifact_root).resolve(strict=True)
        if not resolved.is_relative_to(root) or same_path(resolved, root):
            raise PermissionError("Only files inside the Qronos artifact root can be registered.")
        return self.registry.register_file(
            resolved,
            origin=origin,
            source_conversation_id=provenance.conversation_id,
            source_message_id=provenance.message_id,
            source_request_id=provenance.request_id,
            unread=unread,
        )

    def register_link(
        self,
        url: str,
        *,
        name: str,
        origin: ArtifactOrigin = "Collected by Qronos",
        provenance: ArtifactProvenance = ArtifactProvenance(),
    ) -> Artifact:
        if origin not in _ALLOWED_ORIGINS:
            raise ValueError(f"Unsupported Qronos artifact origin: {origin}")
        return self.registry.register_link(
            url,
            name=name,
            origin=origin,
            source_conversation_id=provenance.conversation_id,
            source_message_id=provenance.message_id,
            source_request_id=provenance.request_id,
        )


def register_qronos_artifact(
    path: str | Path,
    *,
    origin: ArtifactOrigin = "Generated by Qronos",
    conversation_id: str = "",
    message_id: str = "",
    request_id: str = "",
    unread: bool = True,
) -> Artifact:
    return ArtifactProducerRegistry().register_file(
        path,
        origin=origin,
        provenance=ArtifactProvenance(
            conversation_id=conversation_id,
            message_id=message_id,
            request_id=request_id,
        ),
        unread=unread,
    )
